using System.ComponentModel.DataAnnotations;
using Amr.Application.Validators;

namespace Amr.Application.DTOs.Common;

/// <summary>Inputs shared by simulation and comparison requests. Horizon and scenario are fixed by the verified model and are not accepted.</summary>
public abstract record RunRequestBase
{
    /// <summary>Seven values in canonical antibiotic order; 0 susceptible, 1 resistant.</summary>
    [ResistanceProfile]
    public required IReadOnlyList<int> ResistanceProfile { get; init; }

    /// <summary>Generated by the service when omitted; the value used is always returned.</summary>
    [Range(SeedLimits.Min, SeedLimits.Max)]
    public long? EnvironmentSeed { get; init; }

    /// <summary>Seeds the baseline's tie-breaking among susceptible actions. PPO is deterministic and ignores it.</summary>
    [Range(SeedLimits.Min, SeedLimits.Max)]
    public long? PolicySeed { get; init; }
}
